const item = $input.first().json;
let rawText = '';
if (item.output && Array.isArray(item.output) && item.output[0] && item.output[0].content) {
  const ct = item.output[0].content[0] && item.output[0].content[0].text;
  rawText = (typeof ct === 'object' && ct !== null) ? JSON.stringify(ct) : String(ct || '');
}
if (!rawText && typeof item.output === 'string') { rawText = item.output; }
if (!rawText && item.text) { rawText = String(item.text); }
if (!rawText && item.message && item.message.content) { rawText = String(item.message.content); }
rawText = rawText.trim();
const tick3 = String.fromCharCode(96,96,96);
if (rawText.startsWith(tick3)) {
  const nl = rawText.indexOf(10); rawText = rawText.slice(nl + 1);
  const lt = rawText.lastIndexOf(tick3); if (lt !== -1) rawText = rawText.slice(0, lt);
  rawText = rawText.trim();
}
let parsed = null;
try { parsed = JSON.parse(rawText); } catch(e) {}
if (!parsed) {
  const s = rawText.indexOf('{'); const e2 = rawText.lastIndexOf('}');
  if (s !== -1 && e2 !== -1) { try { parsed = JSON.parse(rawText.substring(s, e2+1)); } catch(e) {} }
}
if (!parsed) { parsed = { correct: false, score: 0, feedback: 'Nie udalo sie ocenic odpowiedzi.', suggestion: 'Sprobuj ponownie.' }; }
const body = $('Webhook — Sprawdź Ćwiczenie').first().json.body;
const attemptId = 'attempt_' + body.studentId + '_' + Date.now();
return [{ json: {
  attemptId, studentId: body.studentId, taskId: body.taskId,
  lessonId: body.lessonId, mode: body.mode, question: body.question,
  expectedAnswer: body.expectedAnswer || '', userAnswer: body.userAnswer,
  correct: parsed.correct === true,
  score: typeof parsed.score === 'number' ? parsed.score : 0,
  feedback: String(parsed.feedback || ''),
  suggestion: String(parsed.suggestion || ''),
  createdAt: new Date().toISOString()
}}];

const d = $input.first().json;
const firestoreBody = JSON.stringify({ fields: {
  attemptId: { stringValue: d.attemptId },
  studentId: { stringValue: d.studentId },
  taskId: { stringValue: d.taskId },
  lessonId: { stringValue: d.lessonId },
  mode: { stringValue: d.mode },
  question: { stringValue: d.question },
  expectedAnswer: { stringValue: d.expectedAnswer },
  userAnswer: { stringValue: d.userAnswer },
  correct: { booleanValue: d.correct },
  score: { integerValue: String(d.score) },
  feedback: { stringValue: d.feedback },
  suggestion: { stringValue: d.suggestion },
  createdAt: { stringValue: d.createdAt }
}});
return [{ json: { ...d, firestoreBody } }];
